import { Component, input, output, signal } from '@angular/core';
import { TablerIconComponent, IconPaperclip } from '@tabler/icons-angular';
import { HrmButton } from '../general/hrm-button';
import { HrmTag } from './hrm-tag';
import { HrmUserCell } from '../table-cells/hrm-user-cell';

/** 1 bình luận trong luồng trao đổi. Nhãn hiển thị (roleLabel/time) do bên gọi cấp (i18n-sạch). */
export interface HrmThreadComment {
  /** Tên người bình luận. */
  author: string;
  /** Nhãn vai trò (badge cạnh tên) — VD "Người tạo", "Quản lý trực tiếp". */
  roleLabel?: string;
  /** Hue badge vai trò (blue/green/yellow/gray/red…). Mặc định blue. */
  roleHue?: string;
  /** Mốc thời gian hiển thị (đã format). */
  time?: string;
  /** Nội dung bình luận. */
  text: string;
}

/** hrm-comment-thread — luồng bình luận & trao đổi: danh sách bình luận (avatar màu +
 *  tên + badge vai trò + thời gian + bong bóng nội dung) + ô nhập gửi bình luận mới.
 *  Dùng cho chi tiết đơn từ/hồ sơ. Nhãn qua input (i18n-sạch). Toàn token → tự Light/Dark.
 *
 *  <hrm-comment-thread [comments]="items" placeholder="Nhập bình luận…" sendLabel="Gửi"
 *     (send)="onSend($event)" (attach)="..." /> */
@Component({
  selector: 'hrm-comment-thread',
  imports: [TablerIconComponent, HrmButton, HrmTag, HrmUserCell],
  template: `
    <div class="ct">
      @for (c of comments(); track $index) {
        <div class="ct-item">
          <div class="ct-head">
            <hrm-user-cell [name]="c.author" [colorful]="true" [avatarSize]="28" />
            @if (c.roleLabel) {
              <hrm-tag [color]="$any(c.roleHue || 'gray')" variant="light" size="sm">{{ c.roleLabel }}</hrm-tag>
            }
            <span class="ct-spacer"></span>
            @if (c.time) { <span class="ct-time">{{ c.time }}</span> }
          </div>
          <div class="ct-bubble">{{ c.text }}</div>
        </div>
      }

      <div class="ct-input">
        <input class="ct-field" [value]="draft()" (input)="draft.set($any($event.target).value)"
          (keydown.enter)="submit()" [placeholder]="placeholder()" />
        <button type="button" class="ct-attach" [attr.aria-label]="attachLabel() || null" (click)="attach.emit()">
          <tabler-icon [icon]="icClip" [size]="16" />
        </button>
        <hrm-button variant="primary" [disabled]="!draft().trim()" (click)="submit()">{{ sendLabel() }}</hrm-button>
      </div>
    </div>
  `,
  host: { class: 'hrm-comment-thread' },
  styles: [`
    :host { display: block; }
    .ct { display: flex; flex-direction: column; gap: 12px; }
    .ct-item { display: flex; flex-direction: column; gap: 6px; }
    .ct-head { display: flex; align-items: center; gap: 8px; min-width: 0; }
    .ct-spacer { flex: 1; }
    .ct-time { flex: none; font-size: var(--fs-12); color: var(--text-soft); font-variant-numeric: tabular-nums; }
    /* Bong bóng nội dung — thẳng cột với tên (avatar 28 + gap 8). */
    .ct-bubble {
      margin-left: 36px; padding: 8px 12px; border-radius: var(--radius-md);
      background: var(--bg-surface-subtle); font-size: var(--fs-13); line-height: 1.55; color: var(--text-body);
      white-space: pre-line; overflow-wrap: anywhere;
    }

    /* Hàng nhập: ô nhập · đính kèm · gửi — cao ĐỀU 32px. */
    .ct-input { display: flex; align-items: center; gap: 8px; margin-top: 2px; }
    .ct-field {
      flex: 1; min-width: 0; height: 32px; padding: 0 10px;
      border: 1px solid var(--border-sub); border-radius: var(--radius-md);
      background: var(--bg-surface); color: var(--text-body); font: inherit; font-size: var(--fs-13); outline: none;
      transition: border-color var(--duration-fast, .15s) var(--ease-out, ease);
    }
    .ct-field::placeholder { color: var(--text-soft); }
    .ct-field:focus { border-color: var(--primary-base); }
    .ct-attach {
      display: grid; place-items: center; width: 32px; height: 32px; flex: none;
      border: 1px solid var(--border-sub); background: var(--bg-surface); border-radius: var(--radius-md);
      cursor: pointer; color: var(--icon-secondary);
    }
    .ct-attach:hover { border-color: var(--primary-base); color: var(--icon-primary); }
  `],
})
export class HrmCommentThread {
  /** Danh sách bình luận (cũ → mới). */
  readonly comments = input<HrmThreadComment[]>([]);
  /** Placeholder ô nhập (i18n). */
  readonly placeholder = input('');
  /** Nhãn nút gửi (i18n). */
  readonly sendLabel = input('');
  /** Nhãn a11y nút đính kèm (i18n). */
  readonly attachLabel = input('');
  /** Gửi bình luận mới — phát nội dung; bên gọi tự append vào danh sách. */
  readonly send = output<string>();
  /** Bấm nút đính kèm tệp. */
  readonly attach = output<void>();

  protected readonly draft = signal('');
  protected readonly icClip = IconPaperclip;

  protected submit(): void {
    const t = this.draft().trim();
    if (!t) return;
    this.send.emit(t);
    this.draft.set('');
  }
}
