import {
  Component, ElementRef, afterEveryRender, computed, effect, input, output, signal, viewChild, viewChildren,
} from '@angular/core';
import { TranslateModule } from '@ngx-translate/core';
import {
  TablerIconComponent, IconCheck, IconEdit, IconDotsVertical, IconDownload,
} from '@tabler/icons-angular';
import { NzDropDownModule } from 'ng-zorro-antd/dropdown';
import { NzMenuModule } from 'ng-zorro-antd/menu';
import {
  HrmButton, HrmTag, HrmUserCell, HrmStatusCell, HrmFileCell, HrmProgressCell,
  HrmApprovalFlow, HrmApprovalStep, HrmCommentThread, HrmThreadComment,
  HrmWorkflowStatus, HrmActionTone, HRM_WORKFLOW_ACTIONS,
} from 'hrm-ui';
import { EmpRow, STAGES, fmtDM, fmtHMDMY, empHist } from './_people';

/** 1 nút trong action bar chi tiết — gộp hành động quy trình (wf) + hành động bản ghi (detail).
 *  tone = màu ngữ nghĩa; icon = Tabler icon đứng trước nhãn (nút icon + text). */
interface DetailAction {
  key: string;
  label: string;
  tone: HrmActionTone;
  icon: unknown;
  kind: 'wf' | 'detail';
}

/** Thẻ chi tiết nhân viên — layout theo màn phê duyệt chuẩn (thông tin · quá trình ·
 *  tệp · lịch sử). Dùng CHUNG cho mọi surface: master/side/center (trong hrm-detail-peek)
 *  và trang bản ghi toàn trang/tab mới (list-record). */
@Component({
  selector: 'sg-emp-detail',
  imports: [TranslateModule, TablerIconComponent, NzDropDownModule, NzMenuModule, HrmButton, HrmTag, HrmUserCell, HrmStatusCell, HrmFileCell, HrmProgressCell, HrmApprovalFlow, HrmCommentThread],
  template: `
    @if (emp(); as r) {
      <div class="pk">
        <!-- Nhận diện + TRẠNG THÁI (component Status, thay tag giai đoạn cũ). -->
        <div class="pk-head2">
          <hrm-user-cell [name]="$any(r['name'])" [sub]="'NV-000' + r['id'] + ' · ' + r['dept']" [colorful]="true" [avatarSize]="44" />
          @if (wfStatus()) {
            <hrm-status [preset]="wfStatus()!" variant="badge" [dot]="true" />
          } @else {
            <hrm-tag [color]="$any(stageHue(r))" variant="light" size="sm">{{ stageLabel(r) }}</hrm-tag>
          }
        </div>

        <!-- Action bar GỘP (quy trình + bản ghi): full-width, STICKY khi cuộn; responsive KHÔNG
             rớt hàng — nút dư thu vào ⋮ (kế bên nút more).
             PAGE MODE (toàn trang/tab): ẩn — action bar do TRANG tự dựng thành topnav full-width. -->
        @if (showActionBar()) {
          <div class="pk-actions" #actbar>
            @for (a of actions(); track a.key; let i = $index) {
              <hrm-button #actbtn [variant]="a.tone === 'neutral' ? 'default' : 'primary'" size="md"
                [attr.data-tone]="a.tone" [hidden]="i >= visibleCount()" (click)="run(a)">
                <tabler-icon [icon]="$any(a.icon)" [size]="15" /> {{ a.label }}
              </hrm-button>
            }
            @if (visibleCount() < actions().length) {
              <button type="button" class="pk-more" aria-label="Thêm thao tác"
                nz-dropdown [nzDropdownMenu]="moreMenu" nzTrigger="click" nzPlacement="bottomRight">
                <tabler-icon [icon]="more" [size]="16" />
              </button>
              <nz-dropdown-menu #moreMenu="nzDropdownMenu">
                <ul nz-menu>
                  @for (a of actions(); track a.key; let i = $index) {
                    @if (i >= visibleCount()) {
                      <li nz-menu-item [class.pk-mi-danger]="a.danger" (click)="run(a)">{{ a.label }}</li>
                    }
                  }
                </ul>
              </nz-dropdown-menu>
            }
          </div>
        }

        <section class="pk-sec">
          <h4 class="pk-h">Thông tin nhân viên</h4>
          <dl class="pk-list">
            <dt>Email</dt><dd>{{ r['email'] }}</dd>
            <dt>Chức vụ</dt><dd>{{ $any(r['role']) | translate }}</dd>
            <dt>Phòng ban</dt><dd>{{ r['dept'] }}</dd>
            <dt>Thâm niên</dt><dd>{{ $any(r['tenure']) | translate }}</dd>
            <dt>Quản lý trực tiếp</dt><dd>{{ r['manager'] }}</dd>
            <dt>Chuyên cần</dt>
            <dd><hrm-status-cell [status]="r['status'] === 'active' ? 'success' : 'error'"
              [label]="(r['status'] === 'active' ? 'docs.enterpriseGrid.statusActive' : 'docs.enterpriseGrid.statusAbsent') | translate"
              variant="dot" /></dd>
          </dl>
        </section>

        <section class="pk-sec">
          <h4 class="pk-h">Quá trình thử việc</h4>
          <dl class="pk-list">
            <dt>Kỳ thử việc</dt><dd>{{ fmt(r['start']) }} → {{ fmt(r['end']) }}</dd>
            <dt>Tiến độ</dt>
            <dd><hrm-progress-cell [value]="$any(r['progress'])" [color]="r['stage'] === 'done' ? 'green' : 'primary'" /></dd>
          </dl>
        </section>

        <section class="pk-sec">
          <h4 class="pk-h">Quy trình phê duyệt</h4>
          <hrm-approval-flow [steps]="approvalSteps(r)" [collapsedCount]="4"
            moreLabel="+2 người phê duyệt" collapseLabel="Thu gọn" />
        </section>

        <section class="pk-sec">
          <h4 class="pk-h">Tệp đính kèm</h4>
          <div class="pk-file">
            <hrm-file-cell [name]="'ho-so-NV-000' + r['id'] + '.pdf'" size="512 KB" />
            <button type="button" class="pk-dl" aria-label="Tải xuống"><tabler-icon [icon]="download" [size]="16" /></button>
          </div>
        </section>

        <section class="pk-sec">
          <h4 class="pk-h">Lịch sử</h4>
          <div class="pk-tl">
            @for (h of hist(r); track h.text) {
              <div class="pk-tl-i" [class.is-on]="h.on">
                <div class="pk-tl-t">{{ h.time }}</div>
                <div class="pk-tl-x">{{ h.text }}</div>
              </div>
            }
          </div>
        </section>

        <section class="pk-sec">
          <h4 class="pk-h">Bình luận &amp; Trao đổi</h4>
          <hrm-comment-thread [comments]="allComments()" placeholder="Nhập bình luận…"
            sendLabel="Gửi" attachLabel="Đính kèm tệp" (send)="onSend($event)" />
        </section>
      </div>
    }
  `,
  host: { class: 'sg-emp-detail', '[attr.data-page-mode]': "pageMode() ? '' : null" },
  styles: [`
    :host { display: block; }
    /* padding-top bù cho phần surface đã bỏ padding-top (để action bar ghim flush) → nhịp trên đều. */
    .pk { display: flex; flex-direction: column; gap: var(--space-3-5); padding-top: var(--space-4); }
    .pk-head2 { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--space-2); }
    /* Action bar: full-width, KHÔNG rớt hàng (nowrap) — dư thu vào ⋮; STICKY ghim FLUSH sát header
       (surface đã bỏ padding-top → top:0 = sát header, không hở khe padding). padding trên = dưới
       (đều); margin-bottom âm triệt tiêu flex-gap → nền bar phủ kín, content cuộn không "xuyên" qua
       khe dưới; border-bottom = DUY NHẤT 1 đường (section kề bỏ border-top). */
    .pk-actions {
      display: flex; align-items: center; gap: var(--space-2); flex-wrap: nowrap; width: 100%; min-width: 0;
      position: sticky; top: 0; z-index: 5;
      padding: var(--space-2) 0; margin-bottom: calc(-1 * var(--space-3-5));
      background: var(--bg-surface); border-bottom: 1px solid var(--border-soft);
    }
    /* Section kề ngay dưới bar: bỏ đường kẻ trên (tránh double divider) + bỏ padding-top thừa. */
    .pk-actions + .pk-sec { border-top: 0; padding-top: 0; }

    /* PAGE MODE: action bar nội bộ ẩn (trang tự dựng topnav). Card của trang đã padding đều
       → bỏ padding-top bù của .pk (chỉ cần cho surface drawer) → nhịp trên = trái/phải/dưới. */
    :host([data-page-mode]) .pk { padding-top: 0; }
    .pk-actions hrm-button[hidden] { display: none; }
    /* Nút gọn: gap icon↔text nhỏ + padding ngang thu lại (token). */
    .pk-actions hrm-button tabler-icon { margin-right: var(--space-0-5); }
    .pk-actions hrm-button ::ng-deep .ant-btn { padding-inline: var(--space-2); gap: var(--space-0-5); }
    /* Tông màu nút hành động (nền đặc theo ngữ nghĩa) — đồng bộ hrm-workflow-actions. */
    .pk-actions hrm-button[data-tone='error'] ::ng-deep .ant-btn { background: var(--error-base); border-color: var(--error-base); color: var(--static-white, #fff); }
    .pk-actions hrm-button[data-tone='error'] ::ng-deep .ant-btn:hover { filter: brightness(0.95); }
    .pk-actions hrm-button[data-tone='warning'] ::ng-deep .ant-btn { background: var(--warning-base); border-color: var(--warning-base); color: var(--static-white, #fff); }
    .pk-actions hrm-button[data-tone='warning'] ::ng-deep .ant-btn:hover { filter: brightness(0.95); }
    .pk-actions hrm-button[data-tone='violet'] ::ng-deep .ant-btn { background: var(--purple-500); border-color: var(--purple-500); color: var(--static-white, #fff); }
    .pk-actions hrm-button[data-tone='violet'] ::ng-deep .ant-btn:hover { filter: brightness(0.95); }
    .pk-more { flex: none; margin-left: auto; }
    /* Nút ⋮ cao ĐÚNG bằng ant-btn size md (32px) → hàng nút đồng đều. */
    .pk-more { display: inline-flex; align-items: center; justify-content: center; width: 32px; height: 32px; border: 1px solid var(--border-sub); background: var(--bg-surface); border-radius: var(--radius-md); cursor: pointer; color: var(--text-sub); }
    .pk-mi-danger { color: var(--error-base); }
    .pk-more:hover { border-color: var(--primary-base); color: var(--text-strong); }
    .pk-h { margin: 0 0 8px; font-size: var(--fs-12); font-weight: 600; text-transform: uppercase; letter-spacing: .04em; color: var(--text-sub); }
    .pk-sec { border-top: 1px solid var(--border-soft); padding-top: 12px; }
    .pk-list { display: grid; grid-template-columns: 118px 1fr; gap: 8px 12px; margin: 0; align-items: center; }
    .pk-list dt { font-size: var(--fs-13); color: var(--text-sub); }
    .pk-list dd { margin: 0; font-size: var(--fs-13); color: var(--text-body); min-width: 0; }
    .pk-file { display: flex; align-items: center; justify-content: space-between; gap: 8px; border: 1px solid var(--border-soft); border-radius: var(--radius-md); padding: 8px 10px; }
    .pk-dl { display: grid; place-items: center; width: 30px; height: 30px; flex: none; border: 0; background: transparent; border-radius: var(--radius-md); cursor: pointer; color: var(--icon-secondary); }
    .pk-dl:hover { background: var(--bg-surface-subtle); color: var(--icon-primary); }
    .pk-tl { display: flex; flex-direction: column; }
    .pk-tl-i { position: relative; padding: 0 0 12px 18px; }
    .pk-tl-i:last-child { padding-bottom: 0; }
    .pk-tl-i::before { content: ''; position: absolute; left: 3px; top: 4px; width: 8px; height: 8px; border-radius: 50%; background: var(--neutral-300); }
    .pk-tl-i.is-on::before { background: var(--primary-base); }
    .pk-tl-i::after { content: ''; position: absolute; left: 6.5px; top: 14px; bottom: 2px; width: 1px; background: var(--border-soft); }
    .pk-tl-i:last-child::after { display: none; }
    .pk-tl-t { font-size: var(--fs-12); color: var(--text-soft); }
    .pk-tl-x { font-size: var(--fs-13); color: var(--text-body); }
  `],
})
export class SgEmpDetail {
  /** Bản ghi nhân viên hiển thị. */
  readonly emp = input<EmpRow | null>(null);
  /** Trạng thái quy trình (State Machine) — có → hiện chip status + các nút hành động quy trình. */
  readonly wfStatus = input<HrmWorkflowStatus | null>(null);
  /** Chế độ TRANG (toàn trang/tab mới): action bar ghim flush sát top vùng cuộn shell (bù padding
   *  pad-lg 32) + trải full bề rộng page content. Mặc định false (dùng trong surface drawer/modal). */
  readonly pageMode = input(false);
  /** Surface hiện tại (peek truyền vào): master/side/center → hành động do FOOTER cố định của peek
   *  đảm nhiệm (chuẩn DS, đồng bộ 3 surface). pageMode (full/tab) → topnav riêng. */
  readonly surfaceMode = input<string>('');
  /** Action bar NỘI BỘ tắt cho mọi surface peek (master/side/center) — action đã ghim FOOTER cố định
   *  của peek; pageMode dùng topnav. Chỉ bật khi render trần (không surface, không pageMode). */
  protected readonly showActionBar = computed(() => {
    const m = this.surfaceMode();
    return !this.pageMode() && m !== 'center' && m !== 'master' && m !== 'side';
  });
  /** Phát key hành động quy trình (approve/reject/…) để bên ngoài chuyển trạng thái. */
  readonly wfAction = output<string>();

  private readonly bar = viewChild<ElementRef<HTMLElement>>('actbar');
  private readonly btns = viewChildren('actbtn', { read: ElementRef });
  /** Số nút hiện trên hàng (còn lại thu vào ⋮). Mặc định lớn → render hết để đo. */
  protected readonly visibleCount = signal(99);
  private widths: number[] = [];

  /** Gộp hành động: nút quy trình (theo State Machine) trước, rồi hành động bản ghi cố định. */
  protected readonly actions = computed<DetailAction[]>(() => {
    const wf = this.wfStatus();
    const wfActs: DetailAction[] = wf
      ? HRM_WORKFLOW_ACTIONS[wf].map((a) => ({
          key: 'wf:' + a.key, label: a.vi, tone: a.tone, icon: a.icon, kind: 'wf' as const,
        }))
      : [];
    return [
      ...wfActs,
      { key: 'approveOfficial', label: 'Duyệt chính thức', tone: 'primary', icon: this.check, kind: 'detail' },
      { key: 'editProfile', label: 'Sửa hồ sơ', tone: 'neutral', icon: this.edit, kind: 'detail' },
    ];
  });

  /** Thực hiện hành động — quy trình thì phát ra ngoài; bản ghi để demo (no-op). */
  protected run(a: DetailAction): void {
    if (a.kind === 'wf') this.wfAction.emit(a.key.slice(3));
  }

  constructor() {
    // Đổi bản ghi → xoá bình luận nháp đã gửi của bản ghi trước (demo, không backend).
    effect(() => { this.emp(); this.extra.set([]); });
    // Đổi bộ hành động (theo trạng thái) → render lại toàn bộ để đo lại chiều rộng.
    effect(() => { this.actions(); this.widths = []; this.visibleCount.set(99); });
    // Sau mỗi lần render: tính lại số nút vừa hàng, dư thu vào ⋮ (chạy cả khi resize).
    afterEveryRender(() => this.recompute());
  }

  /** Đo bề rộng nút hiện + so với bề rộng thanh → set số nút hiển thị; phần dư vào ⋮. */
  private recompute(): void {
    const bar = this.bar()?.nativeElement;
    const btns = this.btns();
    if (!bar || !btns.length) return;
    btns.forEach((b, i) => { const w = b.nativeElement.offsetWidth; if (w > 0) this.widths[i] = w; });
    const n = this.actions().length;
    const gap = 8, moreW = 34;
    const avail = bar.clientWidth;
    const full = this.widths.slice(0, n).reduce((s, w, i) => s + (w || 0) + (i ? gap : 0), 0);
    let count: number;
    if (full <= avail) {
      count = n;
    } else {
      let used = 0; count = 0;
      for (let i = 0; i < n; i++) {
        const w = (this.widths[i] || 0) + (i ? gap : 0);
        if (used + w + gap + moreW > avail) break;
        used += w; count++;
      }
      count = Math.max(1, count);
    }
    this.visibleCount.set(count);
  }

  /** Người duyệt cấp 2 (GĐ khối) / cấp 3 (Nhân sự) — ĐỘNG theo bản ghi: nếu QLTT của
   *  nhân viên trùng người mặc định thì thay người khác — 1 người KHÔNG duyệt 2 cấp. */
  private gdOf(r: EmpRow): string { return r['manager'] === 'Phạm Hoàng Nam' ? 'Đỗ Quang Vinh' : 'Phạm Hoàng Nam'; }
  private nsOf(r: EmpRow): string { return r['manager'] === 'Lê Thị Thu Hương' ? 'Nguyễn Thị Mai' : 'Lê Thị Thu Hương'; }

  /** Quy trình duyệt theo mẫu chuẩn: Gửi yêu cầu (người tạo) → các cấp quản lý.
   *  Badge chỉ hiện khi có nghĩa: bước đang chờ = "Chờ duyệt", bước đã duyệt = "Đã duyệt";
   *  bước chưa tới KHÔNG badge. done = duyệt hết · doing = cấp 1 đang chờ · todo = tất cả chưa tới. */
  protected approvalSteps(r: EmpRow): HrmApprovalStep[] {
    const st = String(r['stage']);
    const gd = this.gdOf(r), ns = this.nsOf(r);
    const sent: HrmApprovalStep = {
      title: 'Gửi yêu cầu', name: String(r['name']), role: String(r['dept']),
      state: 'approved', time: fmtHMDMY(r['start'], '08:30'),
    };
    if (st === 'done') {
      return [
        sent,
        { title: 'Quản lý cấp 1', name: String(r['manager']), role: 'Quản lý trực tiếp', state: 'approved', stateLabel: 'Đã duyệt', time: fmtHMDMY(r['end'], '09:15') },
        { title: 'Quản lý cấp 2', name: gd, role: 'Giám đốc khối', state: 'approved', stateLabel: 'Đã duyệt', time: fmtHMDMY(r['end'], '10:40') },
        { title: 'Quản lý cấp 3', name: ns, role: 'Phòng Nhân sự', state: 'approved', stateLabel: 'Đã duyệt', time: fmtHMDMY(r['end'], '14:00') },
        { title: 'Quản lý cấp 4', name: 'Đỗ Quang Vinh', role: 'Phó Tổng giám đốc', state: 'approved', stateLabel: 'Đã duyệt', time: fmtHMDMY(r['end'], '15:20') },
        { title: 'Quản lý cấp 5', name: 'Vũ Đình Long', role: 'Tổng giám đốc', state: 'approved', stateLabel: 'Đã duyệt', time: fmtHMDMY(r['end'], '16:05') },
      ];
    }
    // Chưa duyệt xong: hồ sơ ĐÃ gửi (bước 1 ✓) → bước kế tiếp LUÔN là "đang chờ" (current)
    // — không có trạng thái "đã gửi mà không ai đang xử lý".
    return [
      sent,
      { title: 'Quản lý cấp 1', name: String(r['manager']), role: 'Quản lý trực tiếp',
        state: 'current', stateLabel: 'Chờ duyệt' },
      { title: 'Quản lý cấp 2', name: gd, role: 'Giám đốc khối', state: 'waiting' },
      { title: 'Quản lý cấp 3', name: ns, role: 'Phòng Nhân sự', state: 'waiting' },
      { title: 'Quản lý cấp 4', name: 'Đỗ Quang Vinh', role: 'Phó Tổng giám đốc', state: 'waiting' },
      { title: 'Quản lý cấp 5', name: 'Vũ Đình Long', role: 'Tổng giám đốc', state: 'waiting' },
    ];
  }

  /** Bình luận nền (demo) + bình luận vừa gửi trong phiên — ĐỒNG BỘ theo giai đoạn:
   *  Chờ nhận việc = mới có người tạo · Đang thử việc = QLTT đã phản hồi ·
   *  Chính thức = thêm Nhân sự (đúng người duyệt cấp 3) xác nhận, khớp Lịch sử. */
  private readonly extra = signal<HrmThreadComment[]>([]);
  protected readonly allComments = computed<HrmThreadComment[]>(() => {
    const r = this.emp();
    if (!r) return this.extra();
    const st = String(r['stage']);
    const out: HrmThreadComment[] = [{
      author: String(r['name']), roleLabel: 'Người tạo', roleHue: 'gray',
      time: `${fmtDM(r['start'])} 09:20`,
      text: 'Em đã nộp đủ hồ sơ và bàn giao đầu việc theo hướng dẫn. Anh/chị xem xét giúp em ạ.',
    }];
    if (st !== 'todo') {
      out.push({
        author: String(r['manager']), roleLabel: 'Quản lý trực tiếp', roleHue: 'gray',
        time: `${fmtDM(r['start'])} 10:05`,
        text: 'Anh đã nhận hồ sơ. Sẽ theo dõi và đánh giá vào cuối kỳ thử việc.',
      });
    }
    if (st === 'done') {
      out.push({
        author: this.nsOf(r), roleLabel: 'Nhân sự', roleHue: 'gray',
        time: `${fmtDM(r['end'])} 14:05`,
        text: 'Hồ sơ đã được duyệt đủ các cấp. Đã chuyển trạng thái Chính thức.',
      });
    }
    return [...out, ...this.extra()];
  });
  protected onSend(text: string): void {
    this.extra.update((list) => [...list, {
      author: 'Đặng Anh', roleLabel: 'Nhân sự', roleHue: 'gray', time: 'Vừa xong', text,
    }]);
  }

  protected readonly check = IconCheck;
  protected readonly edit = IconEdit;
  protected readonly more = IconDotsVertical;
  protected readonly download = IconDownload;

  protected readonly fmt = fmtDM;
  protected readonly hist = empHist;
  protected stageLabel(r: EmpRow): string { return STAGES[String(r['stage'])]?.label ?? ''; }
  protected stageHue(r: EmpRow): string { return STAGES[String(r['stage'])]?.hue ?? 'gray'; }
}
