/** dd/MM cố định (không theo locale trình duyệt). */
export function fmtDM(v: unknown): string {
  const d = new Date(String(v ?? ''));
  return isNaN(d.getTime()) ? '' : `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}`;
}

/** dd/mm/yyyy — dùng cho mốc thời gian đầy đủ (kèm giờ hh:mm phía trước). */
export function fmtDMY(v: unknown): string {
  const d = new Date(String(v ?? ''));
  return isNaN(d.getTime()) ? '' : `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
}

/** Mốc "hh:mm dd/mm/yyyy" — giờ trước, ngày sau (đúng yêu cầu Quy trình phê duyệt). */
export function fmtHMDMY(v: unknown, hm: string): string {
  const dmy = fmtDMY(v);
  return dmy ? `${hm} ${dmy}` : hm;
}

/** Lịch sử hồ sơ theo giai đoạn (mốc suy từ kỳ thử việc — dữ liệu demo). */
export function empHist(r: EmpRow): { time: string; text: string; on: boolean }[] {
  const out = [{ time: `${fmtDM(r['start'])} 08:30`, text: 'Tạo hồ sơ nhân viên', on: false }];
  if (r['stage'] === 'todo') { out.push({ time: fmtDM(r['start']), text: 'Chờ nhận việc', on: true }); return out; }
  out.push({ time: `${fmtDM(r['start'])} 09:00`, text: 'Bắt đầu thử việc', on: r['stage'] === 'doing' });
  if (r['stage'] === 'done') out.push({ time: `${fmtDM(r['end'])} 17:00`, text: 'Chuyển chính thức', on: true });
  return out;
}
